						image {
							width: 100%;
							height: 100%;
							border-radius: 50%;
						}
					}
				}
			}

			.form {
				background: #FFFFFF;
			}

			.item {
				padding: 32rpx 40rpx;
				font-size: 28rpx;
				line-height: 40rpx;
				color: #333333;

				/deep/uni-radio {
					vertical-align: middle;
					margin-right: 2rpx;
				}

				/deep/uni-radio .uni-radio-input {
					width: 28rpx;
					height: 28rpx;
					border: 1px solid #E6993A;
				}

				/deep/uni-radio .uni-radio-input.uni-radio-input-checked {
					border: 1px solid #E6993A !important;
					background-color: #E6993A !important;
				}

				/deep/.wx-radio-input {
					width: 29rpx;
					height: 29rpx;
					border: 1px solid #CCCCCC;
				}

				/deep/.wx-radio-input.wx-radio-input-checked {
					border: 1px solid #E6993A !important;
					background-color: #E6993A !important;
				}

				/deep/uni-radio .uni-radio-input.uni-radio-input-checked:before {
					font-size: 15rpx;
				}

				.label {
					margin-right: 48rpx;
				}

				.name {
					padding-left: 26rpx;
					background-repeat: no-repeat;
					background-position: left center;
					background-size: 14rpx;

					&.asterisk {
						background-image: url(data:image/png;base64,);
					}
				}

				.placeholder {
					font-size: 28rpx;
					font-weight: 400;
					color: #CCCCCC;
				}

				.input {
					flex: 1;
					text-align: right;

					.iconfont {
						margin-left: 8rpx;
						font-size: 24rpx;
						color: #999;
						line-height: 15px;
					}

					input {
						font-size: 28rpx;
					}
				}
			}

			.headerT {
				background-image: url(data:image/png;base64,);
				background-repeat: no-repeat;
				background-size: 100% 100%;
				height: 104rpx;
				padding: 32rpx 0 0 40rpx;
				font-weight: 600;
				font-size: 30rpx;
				line-height: 42rpx;
				color: #333333;
				// backdrop-filter: blur(5px);

				.pictrue {
					width: 124rpx;
					height: 22rpx;

					image {
						width: 100%;
						height: 100%;
						display: block;
					}

					&.on {
						transform: rotateX(180deg);
					}
				}
			}
		}
	}
</style>